const TOKEN_PRICE=0.025,LISTING_PRICE=0.10;
function initHeroChart(){const el=document.getElementById('heroChart');let bars='';for(let i=0;i<14;i++){const h=20+Math.random()*80;bars+=`<div class="bar" style="height:${h}%">`}el.innerHTML=bars}
function copyLink(){const link=document.getElementById('refLink');link.select();navigator.clipboard.writeText(link.value).then(()=>alert('Referral link copied!')).catch(()=>alert('Link: '+link.value))}
function shareTwitter(){window.open(`https://twitter.com/intent/tweet?text=Join the Verdis Chain presale and get 20% bonus VRDX! &url=${encodeURIComponent(document.getElementById('refLink').value)}`,'_blank')}
function shareTelegram(){window.open(`https://t.me/share/url?url=${encodeURIComponent(document.getElementById('refLink').value)}&text=Get VRDX tokens at presale price + 20% bonus!`,'_blank')}
function shareDiscord(){copyLink();alert('Link copied! Paste it in Discord: '+document.getElementById('refLink').value)}
function shareWhatsApp(){window.open(`https://wa.me/?text=${encodeURIComponent('Get VRDX tokens at presale price + 20% bonus! '+document.getElementById('refLink').value)}`,'_blank')}
function shareEmail(){window.open(`mailto:?subject=VRDX Token Presale - 20% Bonus&body=Get VRDX tokens at $0.025 (listing $0.10) with 20% bonus: ${document.getElementById('refLink').value}`)}
function calculate(){const t1=+document.getElementById('calcT1').value||0;const t2=+document.getElementById('calcT2').value||0;const t3=+document.getElementById('calcT3').value||0;const avg=+document.getElementById('calcAvg').value||0;const r1=t1*avg*0.10;const r2=t2*avg*0.05;const r3=t3*avg*0.025;const total=r1+r2+r3;const vrdx=total/TOKEN_PRICE;const listingVal=vrdx*LISTING_PRICE;document.getElementById('calcR1').textContent=r1.toLocaleString(undefined,{maximumFractionDigits:0})+' VRDX';document.getElementById('calcR2').textContent=r2.toLocaleString(undefined,{maximumFractionDigits:0})+' VRDX';document.getElementById('calcR3').textContent=r3.toLocaleString(undefined,{maximumFractionDigits:0})+' VRDX';document.getElementById('calcTotal').textContent=vrdx.toLocaleString(undefined,{maximumFractionDigits:0})+' VRDX';document.getElementById('calcUSD').textContent='$'+total.toLocaleString(undefined,{maximumFractionDigits:2});document.getElementById('calcListing').textContent='$'+listingVal.toLocaleString(undefined,{maximumFractionDigits:2})}
function renderLeaderboard(){document.getElementById('leaderbody').innerHTML='<tr><td colspan="6" style="text-align:center;padding:48px 20px;color:var(--text-3);font-size:14px">No affiliates yet — be the first to share your referral link when the IDO goes live!</td></tr>'}
function toggleFAQ(el){el.parentElement.classList.toggle('open')}
initHeroChart();calculate();renderLeaderboard();

async function loadPageMetrics() {
    try {
        const res = await fetch('/rpc', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'chain_getHeader', params: [], id: 1})
        });
        const data = await res.json();
        const height = parseInt(data.result?.number || '0x0', 16);
        document.querySelectorAll('[data-block-height]').forEach(el => {
            el.textContent = '#' + height.toLocaleString();
        });
    } catch(e) {}
}
loadPageMetrics();
setInterval(loadPageMetrics, 15000);
